import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷二·9","description":"易小帖 - 卷二·9","frontmatter":{"title":"卷二·9","description":"易小帖 - 卷二·9"},"headers":[],"relativePath":"classics/yixiaotie/049.md","filePath":"classics/yixiaotie/049.md"}'),o={name:"classics/yixiaotie/049.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷二·9",tabindex:"-1"},[r("卷二·9 "),e("a",{class:"header-anchor",href:"#卷二·9","aria-label":"Permalink to “卷二·9”"},"​")],-1),e("p",null,"七日來複，只從剝之上爻至復之初爻，合七爻，為七日。蓋十二闢卦以剝為陽之將盡，復為陽之初生，故特取二卦為闢卦之驗。則就剝上爻歴坤六爻至復而合為七日。（十二闢卦平分陰陽，陰六卦自五月建午一陰生姤卦始，歴二陰遯，三陰否，四陰觀，五陰剝，而陽將盡矣，至六陰坤則陽既盡，而於是一陽復生，謂之復。）其所以必從剝起者，緣姤遯觀坤，皆別為象義，而惟剝與復則專言陰陽消長之理，與否泰同。故剝復倒對，但觀復而剝在其中，不必別取他象。而惟以復之所始者為剝之所竟，曰七日，如臨觀倒對，但言臨而觀在其中，不必別取他象，而惟以臨之所進為觀之所止，曰八月。（臨進而泰、大壯、夬、乾，反而生姤、遯、否、觀，為八月），此定理亦定例也。侯果謂：十一月天行至子，五月天行至午，凡歴七月，為七日。其不言月而言日者，猶《豳風》以一月為一之日，二月為二之日也。則自十一月子至十月亥，仍是六陽六陰臨觀八月之說，恐闢卦相形例無重見。且八月是月，七日是日，以月作日，究為未安。且六陰六陽亦是六月非七月也。若何氏《訂詁》謂：七日即七月，然非自五月建午掄至十一月建子為七個月，只五月便名七月，周之七月，夏之五月也。則七日二字，專屬五月，一月謂五月，一月而即已來複，大是無理。惟李鼎祚《易解》謂：易軌一歲有四時十二月三百六十五日四分日之一，以坎震離兌四方正卦（坎北方之卦為冬至，震東方之卦為春分，離南方之卦為夏至，兌西方之卦為秋分，此四正卦，若艮巽坤乾，則四隅卦矣）分直四時，每一卦司一季，一爻司一氣，每卦六爻六氣，合之得四六二十四氣，而以十二闢卦直十二月（復十一月起至坤十月止，說見前）每一卦各管四卦（如坤十月卦也，其所管為未濟、蹇、頤、中孚四卦），凡五卦直一月，一爻直一日，合之得五六三十日，是易六十四卦除四正卦不直日外，自十二闢卦以及餘四十八卦，凡六十卦，合之剛得三百六十日，當一歲周天之數，其餘五日四分日之一，則又每日分為八十分，五日分為四百分加之四分日之一，又為二十分，合之得四百二十分，而以六十卦計之，六七四十二，每卦又各得七分，是一卦六爻該所得六日零七分，而以為七日，舉成數也。今剝之至復，隔坤一卦，則正隔六日七分，為七日。此以《易緯》分卦直日之法解易，似乎精確，但其中有大謬者。夫剝之至復，雖曰七日，實在坤亥一月之中，特未嘗外兼他月。如臨觀八月之可以月計，故卻月書日耳。所雲七日，約七爻之日耳。今直限七日，而又非一爻一日，反以六爻該七日，是專以日不以爻，似推曆法，非推易法。固已非是，至實以分卦直日之法計之，則所雲自坤至復者，計坤直十月，凡管四卦坤之至復，必歴未濟蹇頤中孚四卦，而後至於復，則已隔四七二十八日，而況復之所接，又是中孚，並不是坤。若謂中孚與復止隔一卦，陽氣之動，實兆中孚，則於陽生於復，興於復，見天地之心諸語，又齟齬不通，況京焦緯學甚屬矯強，即時月與日，並無分別，積日成月，積月成時，原無有二。今十二直月，既同列直日之數，而獨於直時四卦不錄直日，此皆以曆數強合易數，而究竟不齊不可訓者。至核日則尤謬之謬矣。若近儒因推算不合，又從而小變之謂七日之日，以曆書每日一周天之日言，不以緯書六日七分作一卦之日言，則此說易乎？抑說曆乎？何不通至此。",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
